import{_ as s,l as i,o as e,c as l,v as t,p as d,x as r,d as c,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"递归下降","description":"","frontmatter":{"title":"递归下降","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/recursive-descent.md","filePath":"cs/recursive-descent.md","lastUpdated":1789023840000}'),h={name:"cs/recursive-descent.md"};function E(_,a,m,u,A,T){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="递归下降" tabindex="-1">递归下降 <a class="header-anchor" href="#递归下降" aria-label="Permalink to &quot;递归下降&quot;">​</a></h1><div class="epigraph"><p>每个非终结符一个函数；看当前记号决定用哪条产生式，再按右部依次匹配或递归。</p><footer>—— 据龙书第 4 章；递归下降作为 LL 的手工实现整理</footer></div><p>上一课<a href="/cs/ambiguity-leftrec">二义与左递归</a>给了产生式与推导树。本课不重定义 CFG。缺口是：<strong>分析器</strong>——从记号流建树。最直接的做法是最左推导的手工翻译：非终结符变成过程。本课只处理可递归下降的文法：无左递归、每次看一个记号能决定产生式。FIRST/FOLLOW 的系统计算下一课才写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>文法在纸上，编译器要消费<a href="/cs/regex-lexer">词法</a>的流。递归下降：<code>parseE</code> 看 lookahead，选 \\(E\\to E+T\\) 或 \\(E\\to T\\)——但左递归会令 <code>parseE</code> 尚未读记号就再进 <code>parseE</code>，不停机。缺口先是<strong>改写左递归</strong>为右递归或循环，再写函数。预测失败则报语法错误。</p><p>这是 LL(1) 的直觉实现。本课用一记号前瞻，不写表驱动。</p><h3 id="左递归不是「递归」本身有罪" tabindex="-1">左递归不是「递归」本身有罪 <a class="header-anchor" href="#左递归不是「递归」本身有罪" aria-label="Permalink to &quot;左递归不是「递归」本身有罪&quot;">​</a></h3><p>右递归 \\(T\\to F*T\\) 对应函数末尾递归，可终止。左递归是「不消耗记号的自调用」。改写会改变结合性，要用循环恢复左结合，那是实现细节，本课点名。</p><p><span class="marginnote">龙书把递归下降当作教学分析器。错误恢复（恐慌模式跳到同步记号）本课只承认需要，不写完整策略。后课 LL 表是同一预测的表格化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每个 \\(A\\) 写 <code>parseA</code>：按 lookahead 选产生式，右部终结符 <code>match</code>，非终结符调用。建树：函数返回节点。消除直接左递归：\\(A\\to A\\alpha\\mid\\beta\\) 改为 \\(A\\to\\beta A&#39;\\)，\\(A&#39;\\to\\alpha A&#39;\\mid\\varepsilon\\)。</p>',11)),(e(),d(p,null,{default:r(()=>[n(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOK%5B%22%E5%BD%93%E5%89%8D%E8%AE%B0%E5%8F%B7%22%5D%20--%3E%20PRED%5B%22%E9%80%89%E4%BA%A7%E7%94%9F%E5%BC%8F%22%5D%0A%20%20PRED%20--%3E%20MATCH%5B%22%E5%8C%B9%E9%85%8D%E7%BB%88%E7%BB%93%E7%AC%A6%E6%88%96%E9%80%92%E5%BD%92%22%5D%0A%20%20MATCH%20--%3E%20NODE%5B%22%E8%BF%94%E5%9B%9E%E5%AD%90%E6%A0%91%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><a href="/cs/stack-adt">栈与调用</a>实现递归；深度与语法嵌套成正比，不是图的 DFS 边分类。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每个函数的契约：从当前记号起消费 \\(A\\) 的一段，失败则诊断。公共前缀要用提取左因子，否则一个记号看不出选哪条——那已是 LL(1) 冲突，下一课命名。本课若手写时出现「两个分支同一记号」，就该改文法。</p><p>回溯（试一条失败再试另一条）可分析更大语言，最坏指数；主干不用。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不算完整 FIRST/FOLLOW 集合算法。不处理 LR 的移进归约。不把表达式优先级用二十层非终结符写完——可用循环加优先级表，仍属下降族。后课默认：无左递归、可预测的文法有一份递归下降。系统化 FIRST/FOLLOW 与 LL(1) 表是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>递归下降 = 最左推导的函数实现；一看一记号预测。</li><li>左递归必须改写；公共前缀要提取。</li><li>不用指数回溯。</li><li>出处：Aho et al., 龙书第 4 章。</li></ul>',8))])}const b=s(h,[["render",E]]);export{B as __pageData,b as default};
